css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--stone:#E0D9CB;--sand:#BBAFA3;--clay:#8C5B46;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left;background:var(--ink);color:var(--bone)}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.narrow{max-width:1000px}
.pad{padding:160px 0}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--sand)}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:28px 0 32px}
.pw h2{font-family:var(--head);font-weight:500;font-size:60px;line-height:1.08;letter-spacing:0;margin:0;text-wrap:balance;text-indent:-.0333em}
.subline{margin:24px 0 56px;font-family:var(--head);font-weight:500;font-size:28px;color:var(--stone);text-indent:.0357em}
.frame{position:relative;margin:0;aspect-ratio:16/9;border:1px solid rgba(140,91,70,.7);background:radial-gradient(55% 65% at 50% 50%,rgba(140,91,70,.3),rgba(1,10,18,.95)),var(--ink);display:flex;align-items:center;justify-content:center}
.frame:before{content:"";position:absolute;inset:10px;border:1px solid rgba(140,91,70,.25);z-index:1;pointer-events:none}
.poster{position:absolute;inset:0;overflow:hidden}
.poster .os-img{position:absolute;inset:0;width:100%;height:100%;aspect-ratio:auto;padding:0;border:0;background:none}
.poster img{width:100%;height:100%;object-fit:cover;display:block;max-width:none}
.play{position:relative;z-index:2;width:88px;height:88px;border:1px solid var(--clay);border-radius:50%;display:flex;align-items:center;justify-content:center;background:none;cursor:pointer;transition:background .4s;text-decoration:none}
.play:hover{background:rgba(140,91,70,.18)}
.play:after{content:"";border-left:16px solid var(--clay);border-top:10px solid transparent;border-bottom:10px solid transparent;margin-left:5px}
.play:focus-visible{outline:2px solid var(--clay);outline-offset:3px}
.cap{position:absolute;bottom:-34px;left:0;right:0;text-align:center;font-size:16px;color:var(--sand)}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
.js-rv .d2{transition-delay:.24s}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.pw h2{font-size:40px}.subline{font-size:22px;margin-bottom:40px}}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
